couplingCount.statement:
def _root_.couplingCount {Φ} (p : ℕ) (κ : Φ → ℕ → ℕ) n' (ev : Finset Φ) σ σ' e :=
  let t σ := ∑ h ∈ .range n', ite (h = 1 ∧ σ ∉ ev) (κ σ h) 0
  let r σ := ∑ h ∈ .range n', ite (h = 1) 0 (κ σ h)
  let B σ := ∑ h ∈ .range n', h * ite (h = 1) 0 (κ σ h)
  (t σ / p ^ e : ℝ) ⊓ (r σ' + t σ') + r σ / p ^ e + (B σ / p ^ e : ℝ) ⊓ B σ'

existscyclotomicdifferentfactor.statement:
lemma Parameters.exists_cyclotomic_different_factor {R N} [CommRing R] [IsDomain R] [CharZero R] {ζ}
  (hζ : IsPrimitiveRoot ζ N) (l : N.primeFactors) : ∃ r, ∃ M ≤ N, N = l * r ∧ (∀ p ∈ N.primeFactors,
  p ∣ M ↔ p ≠ l) ∧ ∃ V, V ∣ ↑M ∧ (cyclotomic N R).derivative.eval ζ * (ζ ^ r - 1) * M = N * V
